transform.program:
# resolve_candidates.star -- deterministic identity resolution + candidate
# filtering. Predeclared params: messages, thread_replies_items (list or None
# when the thread_replies step was skipped), users, thread_ts (string or
# None), cap. Output via `result`.
#
# Everything here is known-field matching (subtype presence, is_bot lookup,
# thread-root dedup, a numeric cap) -- deliberately NOT semantic judgment.
# The free text itself is never interpreted here; that is extract_fields'
# (the lease's) job alone, per the deterministic-first ladder.

def _user_lookup(users):
    m = {}
    for u in users:
        m[u["id"]] = u
    return m

def _display_name(u):
    if u == None:
        return "unknown"
    dn = u.get("display_name")
    if dn:
        return dn
    rn = u.get("real_name")
    if rn:
        return rn
    return u.get("id", "unknown")

def _is_candidate(msg, user_map):
    if msg.get("subtype") != None:
        return False  # system messages (channel_join, etc.), never a standup post
    uid = msg.get("user")
    if uid == None:
        return False
    u = user_map.get(uid)
    if u != None and u.get("is_bot"):
        return False  # bots (reminder bots, standup bots) never author a standup themselves
    text = msg.get("text")
    if text == None or text == "":
        return False
    return True

def _resolve(messages, thread_replies_items, users, thread_ts, cap):
    user_map = _user_lookup(users)
    candidates = []
    for m in messages:
        if _is_candidate(m, user_map):
            candidates.append({
                "ts": m["ts"],
                "user_id": m["user"],
                "display_name": _display_name(user_map.get(m["user"])),
                "text": m["text"],
                "source": "channel",
            })
    if thread_replies_items != None:
        for r in thread_replies_items:
            # conversations.replies repeats the thread's parent message as its
            # first row; it was already counted above via `messages`, so skip
            # it here rather than double-counting the same post.
            if thread_ts != None and r.get("ts") == thread_ts:
                continue
            if _is_candidate(r, user_map):
                candidates.append({
                    "ts": r["ts"],
                    "user_id": r["user"],
                    "display_name": _display_name(user_map.get(r["user"])),
                    "text": r["text"],
                    "source": "thread_reply",
                })
    candidates = candidates[:cap]
    return {"candidates": candidates, "has_candidates": len(candidates) > 0}

result = _resolve(messages, thread_replies_items, users, thread_ts, cap)
